// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Phishable} from "../src/Phishable.sol";

contract InvMutTest is Test {
    Phishable c;
    function setUp() public { c = new Phishable(address(this)); }
    function testFuzz_property(address nonOwner, uint256 initialBalance) public {
        vm.assume(nonOwner != address(this));
        vm.assume(initialBalance >= 0);
        vm.deal(address(c), initialBalance);
        uint256 balanceBefore = address(c).balance;
        vm.prank(nonOwner);
        try c.withdrawAll(address(0)) { } catch { }
        uint256 balanceAfter = address(c).balance;
        assertTrue(balanceBefore == balanceAfter);
    }
}
